output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper is obliged to take the available cart from the entrance cart station before completing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_entrance_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "entrance_cart_station"
            ]
          },
          "post": "has_entrance_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_must_go_in_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently using the cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_based_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "using_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "using_cart"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than putting it in the cart.",
    "abstraction": {
      "state_properties": {
        "hand_carrying": "handFull",
        "cart_carrying": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_carrying",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_top_left_bay",
    "text": "Anyone who takes a cart is obliged to return it to the top-left cart-return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "using_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_bay",
              "using_cart"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "do_not_abandon_cart_elsewhere",
    "text": "A shopper is prohibited from leaving the cart anywhere other than the designated top-left return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "away_from_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        },
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_cart_through_exit",
    "text": "A shopper is prohibited from exiting the store while still in possession of the cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart",
        "at_store_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "using_cart"
            ]
          },
          "post": null
        },
        "exit_without_cart": {
          "pre": {
            "and": [
              "EXIT",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_return_ends_interactions",
    "text": "Once the cart has been returned to the cart-return bay, the shopper is prohibited from performing any further store interaction.",
    "abstraction": {
      "state_properties": {
        "cart_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "role_specific_interaction_places",
    "text": "Primitive interactions must occur only at places appropriate to their role: cart pickup at the entrance cart station, item pickup at shelf-access cells, and cart return at the return bay.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "cart_return_bay": "at(0,1)",
        "apple_access": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_access": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_access": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_access": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "shelf_access": {
          "or": [
            "apple_access",
            "bread_access",
            "milk_access",
            "eggs_access"
          ]
        }
      },
      "events": {
        "legal_pickup_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "entrance_cart_station"
            ]
          },
          "post": "hasCart"
        },
        "legal_pickup_item": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "shelf_access"
            ]
          },
          "post": null
        },
        "legal_leave_cart": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "cart_return_bay"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          {
            "and": [
              "PICKUP_CART",
              {
                "not": "entrance_cart_station"
              }
            ]
          },
          {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "shelf_access"
              }
            ]
          },
          {
            "and": [
              "LEAVE_CART",
              {
                "not": "cart_return_bay"
              }
            ]
          }
        ]
      }
    }
  }
]
